import java.nio.file.*;import jdk.internal.org.objectweb.asm.*;import jdk.internal.org.objectweb.asm.tree.*;
public class PatchNpc{public static void main(String[]a)throws Exception{ClassNode c=new ClassNode();new ClassReader(Files.readAllBytes(Path.of(a[0]))).accept(c,0);int encode=0,ret=0;for(MethodNode m:c.methods)if(m.name.equals("death"))for(AbstractInsnNode i:m.instructions.toArray()){
 if(i instanceof MethodInsnNode v&&v.owner.equals(c.name)&&v.name.equals("encode")){InsnList p=new InsnList();p.add(new VarInsnNode(Opcodes.ALOAD,8));p.add(new VarInsnNode(Opcodes.ALOAD,2));p.add(new VarInsnNode(Opcodes.ALOAD,0));p.add(new MethodInsnNode(Opcodes.INVOKESTATIC,"dev/zomboid/remains/ProfileCompat","corpse","(Ljava/lang/Object;Ljava/lang/Object;Ljava/lang/Object;)V",false));m.instructions.insertBefore(i,p);encode++;}
 if(i.getOpcode()==Opcodes.IRETURN){InsnList p=new InsnList();LabelNode done=new LabelNode();p.add(new InsnNode(Opcodes.DUP));p.add(new JumpInsnNode(Opcodes.IFEQ,done));p.add(new VarInsnNode(Opcodes.ALOAD,0));p.add(new MethodInsnNode(Opcodes.INVOKESTATIC,"dev/zomboid/remains/ProfileCompat","converted","(Ljava/lang/Object;)V",false));p.add(done);p.add(new FrameNode(Opcodes.F_SAME1,0,null,1,new Object[]{Opcodes.INTEGER}));m.instructions.insertBefore(i,p);ret++;}}
 if(encode!=1||ret<2)throw new IllegalStateException("Unexpected NPC hook sites "+encode+"/"+ret);ClassWriter w=new ClassWriter(ClassWriter.COMPUTE_MAXS);c.accept(w);Files.write(Path.of(a[1]),w.toByteArray());System.out.println("NPC profile before cargo serialization; accepted/queued corpses marked on "+ret+" returns");}}
